import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;
import org.json.*;

public class UserProfileServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger("UserProfile");
    private Connection dbConn;

    @Override
    public void init() throws ServletException {
        try {
            Class.forName("org.postgresql.Driver");
            String dbUrl = System.getenv("DATABASE_URL");
            String dbUser = System.getenv("DB_USER");
            String dbPass = System.getenv("DB_PASS");
            dbConn = DriverManager.getConnection(dbUrl, dbUser, dbPass);
        } catch (Exception e) {
            throw new ServletException("DB init failed", e);
        }
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String action = req.getParameter("action");
        String userId = req.getParameter("user_id");

        resp.setContentType("application/json");
        PrintWriter out = resp.getWriter();

        if ("search".equals(action)) {
            handleSearch(req, resp, out);
        } else if ("profile".equals(action)) {
            handleProfile(userId, out);
        } else {
            out.print("{\"error\": \"unknown action\"}");
        }
    }

    private void handleSearch(HttpServletRequest req, HttpServletResponse resp, PrintWriter out)
            throws IOException {
        String searchTerm = req.getParameter("q");
        String department = req.getParameter("dept");

        if (searchTerm == null || searchTerm.length() > 200) {
            out.print("{\"error\": \"invalid search term\"}");
            return;
        }

        // Basic sanitization - remove obvious SQL keywords
        String filtered = searchTerm.replaceAll("(?i)(DROP|ALTER|TRUNCATE)", "");

        try {
            // Build dynamic query for flexible search across multiple columns
            String query = "SELECT id, display_name, email, department FROM users WHERE " +
                          "(display_name ILIKE '%" + filtered + "%' " +
                          "OR email ILIKE '%" + filtered + "%')";

            if (department != null && !department.isEmpty()) {
                query += " AND department = '" + department + "'";
            }

            query += " ORDER BY display_name LIMIT 50";

            log.info("Search query: " + query);

            Statement stmt = dbConn.createStatement();
            ResultSet rs = stmt.executeQuery(query);

            JSONArray results = new JSONArray();
            while (rs.next()) {
                JSONObject user = new JSONObject();
                user.put("id", rs.getInt("id"));
                user.put("display_name", rs.getString("display_name"));
                user.put("email", rs.getString("email"));
                user.put("department", rs.getString("department"));
                results.put(user);
            }

            out.print(new JSONObject().put("results", results).toString());
            rs.close();
            stmt.close();
        } catch (SQLException e) {
            log.warning("Search failed: " + e.getMessage());
            out.print("{\"error\": \"search failed\"}");
        }
    }

    private void handleProfile(String userId, PrintWriter out) throws IOException {
        if (userId == null || !userId.matches("\\d+")) {
            out.print("{\"error\": \"invalid user id\"}");
            return;
        }
        try {
            PreparedStatement ps = dbConn.prepareStatement(
                "SELECT id, display_name, email, department, bio FROM users WHERE id = ?");
            ps.setInt(1, Integer.parseInt(userId));
            ResultSet rs = ps.executeQuery();
            if (rs.next()) {
                JSONObject user = new JSONObject();
                user.put("id", rs.getInt("id"));
                user.put("display_name", rs.getString("display_name"));
                user.put("email", rs.getString("email"));
                user.put("department", rs.getString("department"));
                user.put("bio", rs.getString("bio"));
                out.print(user.toString());
            } else {
                out.print("{\"error\": \"not found\"}");
            }
            rs.close();
            ps.close();
        } catch (SQLException e) {
            out.print("{\"error\": \"query failed\"}");
        }
    }
}
